builder =>
        {
            builder.AddRetry(new HttpRetryStrategyOptions
            {
                BackoffType = DelayBackoffType.Exponential,
                MaxRetryAttempts = retryOptions.MaxRetryAttempts,
                UseJitter = true,
                MaxDelay = TimeSpan.FromSeconds(retryOptions.MaxRetryDelay)
            })
            .AddCircuitBreaker(new HttpCircuitBreakerStrategyOptions
            {
                SamplingDuration = TimeSpan.FromSeconds(10),
                FailureRatio = retryOptions.FailureRatio,
                MinimumThroughput = retryOptions.MinimumThroughput,
                ShouldHandle = static args =>
                {
                    return ValueTask.FromResult(args is
                    {
                        Outcome.Result.StatusCode:
                            HttpStatusCode.RequestTimeout or
                                HttpStatusCode.TooManyRequests
                    });
                }
            });

            builder.AddTimeout(TimeSpan.FromSeconds(retryOptions.TimeOut));
        }

