options =>
        {
            var path = builder.Configuration.GetValue<string>("GlobalConfiguration:PathToSwaggerGenerator");
            if (!string.IsNullOrEmpty(path))
            {
                options.PathToSwaggerGenerator = path;
            }

            var endpoints = new List<EndpointInformation>();

            var routes = builder.Configuration.GetSection("Routes");

            foreach (var route in routes.GetChildren())
            {
                var firstHost = route.GetSection("DownstreamHostAndPorts:0").Get<OcelotHost>() ?? new OcelotHost(); //0 means pds, TODO, do better when more downstream apis
                firstHost.Scheme = (route[ "DownstreamScheme" ] is { Length: > 0 } scheme) ? scheme : "http";

                var downstreamTemplate = route[ "DownstreamPathTemplate" ] ?? string.Empty;
                var upstreamTemplate = route[ "UpstreamPathTemplate" ] ?? string.Empty;
                var excludePaths = route.GetSection("UpstreamPathExclude").Get<string[]>() ?? [];
                var httpMethods = route.GetSection("UpstreamHttpMethod").Get<string[]>() ?? [];
                var httpMethodsArray = httpMethods.Select(x => new HttpMethod(x)).ToArray();

                endpoints.Add(new EndpointInformation(firstHost.SwaggerUrl, new EndpointFilter(downstreamTemplate, upstreamTemplate, httpMethodsArray, excludePaths)));
            }

            options.RemoteEndpoints = endpoints.ToArray();
        }

