async (globalDictionary) =>
        {

            var entriesDto = GlobalDictionary.Parse(globalDictionary);
            var groupedEntries = entriesDto.GroupBy(e => new { e.CarType, e.ModelYear });


            var results = new List<Result>();
            foreach (var group in groupedEntries)
            {
                var pno3 = group.Key.CarType;
                var modelYear = group.Key.ModelYear;
                var key = new GlobalDictionaryEntriesKey(pno3, modelYear);
                var entries = group.Select(g => new GlobalDictionaryEntry(Enum.Parse<FeatureType>(g.Type), g.Code, g.Name, g.LongName)).ToImmutableList();

                results.Add((await SetCache(key, entries, cancellationToken)).ToResult());
            }

            return results.Merge();
        }

