async mapperResponse =>
            {
                var upstreamIdsForProductsMissingVariantIds = mapperResponse.Response.Products
                    .Where(p => string.IsNullOrEmpty(p.VariantId))
                    .Select(p => p.UpstreamId).ToList();

                if (string.IsNullOrEmpty(mapperResponse.Response.Car.VariantId))
                {
                    var missingCarComponents = GetMissingCarComponents(mapperResponse.Response.Car);

                    return Result.Fail<TransformationResult>(
                        missingCarComponents.Any()
                            ? $"The car variant ID is missing from the Product Mapper response. The following car components could not be resolved: [{string.Join(", ", missingCarComponents)}]."
                            : "The car variant ID is missing from the Product Mapper response.");
                }

                if (upstreamIdsForProductsMissingVariantIds.Any())
                {
                    return Result.Fail<TransformationResult>
                        ($"One or more products in the Product Mapper response are missing variant IDs. Affected upstream product IDs: [{string.Join(',', upstreamIdsForProductsMissingVariantIds)}].");
                }

                return await ResolveMountedWheel(mapperResponse, cancellationToken)
                    .Bind(mountedWheel => BuildCarVariantDetail(query, mapperResponse, mountedWheel))
                    .Bind(async variant => await SaveVariantAndBuildResult(mapperResponse, variant, cancellationToken));
            }

