async (message, cancellationToken) =>
                {
                    if (message == null) return;

                    var messageValue = message.Message?.Value;
                    if (messageValue == null) return;

                    _logger.LogInformation("Kafka Consumer: Received message from topic {Topic}, offset {Offset}", message.Topic, message.Offset);
                    var processor = _messageProcessorFactory.GetProcessor(message!.Topic);
                    (await processor.ProcessMessage(messageValue, message.Message!.Headers, cancellationToken))
                        .LogIfFailed<KafkaConsumerService>();
                }

