async () =>
        {
            var softOffersListTask = _proxy.V1CommercialItemsSoftOffersGetAsync(accept: softOfferAcceptHeader, cancellationToken: cancellationToken);
            var softOfferPackagesListTask = _proxy.V1CommercialItemsSoftOfferPackagesGetAsync(accept: softOfferPackageAcceptHeader, cancellationToken: cancellationToken);
            var softwareListTask = _proxy.V1CommercialItemsSoftwareOptionsGetAsync(accept: softwareOptionAcceptHeader, cancellationToken: cancellationToken);

            await Task.WhenAll(softOffersListTask, softOfferPackagesListTask, softwareListTask);

            var softOfferUpstream = (softOffersListTask.Result.Data ?? []).Select(ToUpstreamEntity);
            var softOfferPackageUpstream = (softOfferPackagesListTask.Result.Data ?? []).Select(ToUpstreamEntity);
            var softwareUpstream = (softwareListTask.Result.Data ?? []).Select(ToUpstreamEntity);

            var upstreamItems = softOfferUpstream.Concat(softOfferPackageUpstream).Concat(softwareUpstream).ToImmutableList();

            return upstreamItems.Count > 0
                ? Result.Ok(upstreamItems)
                : Result.Fail<ImmutableList<UpstreamEntity>>("No upstream items found.");
        }

